mod solution;

fn main() {
    let cases = [
    (r#"weights=[1,3,4,5] values=[1,4,5,7]"#, r#"9"#),
    (r#"weights=[7] values=[10]"#, r#"10"#),
    (r#"
weights=[7] values=[10]
"#, r#"10"#),
    (r#"  
weights=[1,3,4,5] values=[1,4,5,7]
  "#, r#"9"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS zero-one-knapsack");
}
